// ============================================================================
// 4. STORAGE & NETWORK PREFIXES
// ============================================================================

/// Purpose string used in PBKDF2 for deriving ML-DSA-65 deterministic governance keys.
pub const KINETIC_GOVERNANCE_KEY_PURPOSE: &str = concat!(env!("KINETIC_NETWORK_ID_UPPER"), "_GOVERNANCE_KEY_v1_PQC");

/// Prefix for storing owned names in the DHT/Sled storage.
/// Namespaced with NETWORK_ID so forks don't collide on a shared DB path.
pub const DB_PREFIX_OWNED_NAMES: &[u8] = concat!("n:", env!("KINETIC_NETWORK_ID"), "_owned_names").as_bytes();

/// Prefix for storing VDF reveal proofs in the DHT/Sled storage.
pub const DB_PREFIX_REVEAL: &str = concat!("n:", env!("KINETIC_NETWORK_ID"), "_reveal:");

/// Prefix for storing banned peers.
pub const DB_PREFIX_BANNED_PEER: &str = concat!("n:", env!("KINETIC_NETWORK_ID"), "_banned_peer:");

/// Key for storing the last drand round processed.
pub const DB_PREFIX_LAST_DRAND: &[u8] = concat!("n:", env!("KINETIC_NETWORK_ID"), "_last_drand_round").as_bytes();

/// Database name for the ping proxy.
pub const DB_NAME_PING: &str = concat!("n:", env!("KINETIC_NETWORK_ID"), "_ping_db");

/// The libp2p gossipsub topic for governance actions.
/// Namespaced with NETWORK_ID so forks can't bleed governance messages to each other.
pub const GOSSIP_TOPIC_GOVERNANCE: &str = concat!(env!("KINETIC_NETWORK_ID"), "_governance");

/// The libp2p gossipsub topic for Drand beacon pulses.
/// Namespaced with NETWORK_ID so forks have separate pulse channels.
pub const GOSSIP_TOPIC_DRAND: &str = concat!("drand_pulse_", env!("KINETIC_NETWORK_ID"));

// ============================================================================
// 5. ENVIRONMENT VARIABLES
